import { FormEvent, ReactNode, useEffect, useMemo, useState, type ButtonHTMLAttributes, type InputHTMLAttributes, type SelectHTMLAttributes, type TextareaHTMLAttributes } from "react";
import {
  ArrowLeft, ArrowRight, BarChart3, Bell, Building2, Check,
  ClipboardList, Clock3, FileText, Filter, Home, Loader2,
  LogOut, MapPin, Menu, MessageSquare, Plus,
  Search, Send, ShieldCheck, Sparkles, Trash2, UserRound,
  X, Zap,
} from "lucide-react";
import {
  getGetAdminDashboardQueryKey, getGetCitizenDashboardQueryKey,
  getGetIssuesQueryKey, getGetIssueByIdQueryKey, getGetProfileQueryKey,
  useCreateIssue, useDeleteIssue, useForgotPassword, useGetAdminDashboard,
  useGetCitizenDashboard, useGetIssueById, useGetIssues, useGetProfile,
  useLoginUser, useLogoutUser, useRegisterUser, useResetPassword,
  useSendOtp, useUpdateIssue, useUpdateIssuePriority, useUpdateIssueStatus,
  useUpdateProfile, useVerifyOtp, setAuthTokenGetter,
} from "@workspace/api-client-react";
import type {
  AdminDashboard, Dashboard, Issue, IssueInput, IssuePriority,
  User,
} from "@workspace/api-client-react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Link, Route, Router as WouterRouter, Switch, useLocation, useParams } from "wouter";
import { ErrorBoundary } from "@/components/error-boundary";
import NotFound from "@/pages/not-found";

setAuthTokenGetter(() => localStorage.getItem("ward_token"));

const queryClient = new QueryClient();
const statuses = ["Submitted", "Under Review", "Assigned", "In Progress", "Resolved", "Rejected"];
const categories = ["Garbage/Waste", "Road Damage", "Streetlight", "Drainage", "Water Supply", "Public Infrastructure", "Illegal Dumping", "Public Toilet", "Other"];
const wards = ["Ward 01", "Ward 02", "Ward 03", "Ward 04", "Ward 05", "Ward 06"];

function currentUser(): User | null {
  try { return JSON.parse(localStorage.getItem("ward_user") || "null") as User | null; } catch { return null; }
}
function saveSession(token: string, user: User) {
  localStorage.setItem("ward_token", token);
  localStorage.setItem("ward_user", JSON.stringify(user));
}
function clearSession() {
  localStorage.removeItem("ward_token");
  localStorage.removeItem("ward_user");
}
function initials(name = "Resident") {
  return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase();
}
function formatDate(value?: string) {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" });
}

function Button({ children, variant = "primary", className = "", ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "secondary" | "ghost" | "danger" }) {
  const variants = {
    primary: "bg-primary text-primary-foreground hover:-translate-y-0.5 hover:shadow-lg hover:shadow-primary/15",
    secondary: "bg-secondary text-secondary-foreground hover:bg-accent/30",
    ghost: "text-muted-foreground hover:bg-muted hover:text-foreground",
    danger: "bg-destructive text-destructive-foreground hover:-translate-y-0.5",
  };
  return <button {...props} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-50 ${variants[variant]} ${className}`}>{children}</button>;
}
function Input({ label, ...props }: InputHTMLAttributes<HTMLInputElement> & { label?: string }) {
  return <label className="grid gap-2 text-sm font-bold text-foreground">{label && <span>{label}</span>}<input {...props} className={`h-11 rounded-xl border border-input bg-card px-3.5 text-sm font-medium outline-none transition focus:border-primary focus:ring-4 focus:ring-primary/10 ${props.className || ""}`} /></label>;
}
function SelectField({ label, children, ...props }: SelectHTMLAttributes<HTMLSelectElement> & { label?: string }) {
  return <label className="grid gap-2 text-sm font-bold text-foreground">{label && <span>{label}</span>}<select {...props} className={`h-11 rounded-xl border border-input bg-card px-3.5 text-sm font-medium outline-none transition focus:border-primary focus:ring-4 focus:ring-primary/10 ${props.className || ""}`}>{children}</select></label>;
}
function TextArea({ label, ...props }: TextareaHTMLAttributes<HTMLTextAreaElement> & { label?: string }) {
  return <label className="grid gap-2 text-sm font-bold text-foreground">{label && <span>{label}</span>}<textarea {...props} className={`min-h-28 rounded-xl border border-input bg-card px-3.5 py-3 text-sm font-medium outline-none transition focus:border-primary focus:ring-4 focus:ring-primary/10 ${props.className || ""}`} /></label>;
}
function StatusPill({ status }: { status?: string }) {
  const tone = status === "Resolved" ? "bg-emerald-100 text-emerald-800" : status === "Rejected" ? "bg-red-100 text-red-800" : status === "In Progress" ? "bg-amber-100 text-amber-800" : status === "Under Review" ? "bg-violet-100 text-violet-800" : "bg-slate-100 text-slate-700";
  return <span className={`inline-flex w-fit items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-extrabold ${tone}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{status || "Submitted"}</span>;
}
function PriorityPill({ priority }: { priority?: string }) {
  const tone = priority === "Critical" ? "text-red-700 bg-red-50" : priority === "High" ? "text-orange-700 bg-orange-50" : priority === "Medium" ? "text-amber-700 bg-amber-50" : "text-slate-600 bg-slate-100";
  return <span className={`rounded-md px-2 py-1 text-[10px] font-black uppercase tracking-wider ${tone}`}>{priority || "Low"}</span>;
}
function Logo({ dark = false }: { dark?: boolean }) {
  return <Link href="/dashboard" data-testid="link-logo" className="flex items-center gap-3"><span className={`grid h-10 w-10 place-items-center rounded-[14px] ${dark ? "bg-accent text-primary" : "bg-primary text-accent"}`}><Building2 size={20} strokeWidth={2.5} /></span><span className={`text-lg font-extrabold tracking-tight ${dark ? "text-sidebar-foreground" : "text-foreground"}`}>Ward<span className="text-accent">line</span></span></Link>;
}

function Notice({ children, type = "success" }: { children: ReactNode; type?: "success" | "error" | "info" }) {
  const tone = type === "error" ? "border-red-200 bg-red-50 text-red-800" : type === "info" ? "border-blue-200 bg-blue-50 text-blue-800" : "border-emerald-200 bg-emerald-50 text-emerald-800";
  return <div className={`flex items-center gap-2 rounded-xl border px-3 py-2.5 text-sm font-semibold ${tone}`}><Check size={16} />{children}</div>;
}
function LoadingState() {
  return <div className="grid gap-4"><div className="h-24 animate-pulse rounded-2xl bg-muted" /><div className="h-56 animate-pulse rounded-2xl bg-muted" /></div>;
}
function ErrorState({ onRetry }: { onRetry?: () => void }) {
  return <div className="rounded-2xl border border-red-200 bg-red-50 p-8 text-center"><div className="mx-auto mb-3 grid h-11 w-11 place-items-center rounded-full bg-red-100 text-red-700"><X /></div><h3 className="font-extrabold text-red-900">We couldn’t load that</h3><p className="mt-1 text-sm text-red-700">Please check your connection and try again.</p>{onRetry && <Button onClick={onRetry} variant="secondary" className="mt-4">Try again</Button>}</div>;
}

function AuthLayout({ eyebrow, title, children, aside = "A better street starts with someone taking the first step." }: { eyebrow: string; title: string; children: ReactNode; aside?: string }) {
  return <div className="noise min-h-[100dvh] bg-background"><div className="grid min-h-[100dvh] lg:grid-cols-[minmax(360px,42%)_1fr]">
    <aside className="relative hidden overflow-hidden bg-primary p-10 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-32 -top-32 h-96 w-96 rounded-full border-[44px] border-accent/20" /><div className="absolute bottom-20 -left-28 h-72 w-72 rounded-full border-[32px] border-accent/15" /><div className="relative"><Logo dark /><div className="mt-28 max-w-sm"><div className="label-mono text-accent">Civic service, made human</div><p className="display-serif mt-5 text-5xl leading-[.98]">{aside}</p></div></div><div className="relative flex items-center gap-3 text-sm text-primary-foreground/65"><ShieldCheck size={16} /><span>Secure municipal service workspace</span></div></aside>
    <main className="flex items-center justify-center p-5 sm:p-10"><div className="w-full max-w-[460px] page-enter"><div className="mb-10 lg:hidden"><Logo /></div><div className="mb-8"><div className="label-mono text-muted-foreground">{eyebrow}</div><h1 className="display-serif mt-3 text-4xl leading-none text-foreground sm:text-5xl">{title}</h1></div>{children}</div></main>
  </div></div>;
}
function AuthFooter({ children }: { children: ReactNode }) { return <p className="mt-7 text-center text-sm text-muted-foreground">{children}</p>; }

function LoginPage() {
  const [, setLocation] = useLocation();
  const login = useLoginUser();
  const [form, setForm] = useState({ identifier: "", password: "" });
  const [error, setError] = useState("");
  const submit = (event: FormEvent) => { event.preventDefault(); setError(""); login.mutate({ data: form }, { onSuccess: (response) => { saveSession(response.token, response.user); setLocation(response.user.role === "admin" ? "/admin/dashboard" : "/dashboard"); }, onError: (err) => setError((err as Error).message || "Sign in failed") }); };
  return <AuthLayout eyebrow="Welcome back" title="Keep your ward moving." aside="Report what needs attention. Follow the work as it gets done."><form onSubmit={submit} className="grid gap-5">
    {error && <Notice type="error">{error}</Notice>}<Input label="Email or mobile number" autoComplete="username" value={form.identifier} onChange={(e) => setForm({ ...form, identifier: e.target.value })} placeholder="you@example.com" required data-testid="input-login-identifier" /><Input label="Password" type="password" autoComplete="current-password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="Enter your password" required data-testid="input-login-password" /><div className="flex justify-end"><Link href="/forgot-password" className="text-sm font-bold text-primary hover:text-accent-foreground" data-testid="link-forgot-password">Forgot password?</Link></div><Button type="submit" disabled={login.isPending} className="h-12" data-testid="button-login">{login.isPending ? <Loader2 className="animate-spin" size={17} /> : <ArrowRight size={17} />}Sign in</Button>
    <div className="rounded-2xl border border-dashed border-input bg-secondary/50 p-4 text-sm"><div className="flex items-center gap-2 font-extrabold"><Sparkles size={15} className="text-accent-foreground" />Demo access</div><p className="mt-2 text-muted-foreground">Citizen: <b>citizen@example.com</b> · <b>citizen123</b><br />Admin: <b>admin@example.com</b> · <b>admin123</b></p></div>
  </form><AuthFooter>New to Wardline? <Link href="/register" className="font-extrabold text-primary" data-testid="link-register">Create a resident account</Link></AuthFooter></AuthLayout>;
}

function RegisterPage() {
  const [, setLocation] = useLocation(); const register = useRegisterUser(); const [error, setError] = useState(""); const [form, setForm] = useState({ name: "", email: "", mobile: "", password: "", ward: "Ward 01", address: "" });
  const submit = (e: FormEvent) => { e.preventDefault(); setError(""); register.mutate({ data: form }, { onSuccess: () => { localStorage.setItem("pending_email", form.email); setLocation("/verify-otp"); }, onError: (err) => setError((err as Error).message || "Registration failed") }); };
  return <AuthLayout eyebrow="Join your ward" title="Make your neighborhood heard." aside="Your report is a small act of care. Together, those acts change a whole ward."><form onSubmit={submit} className="grid gap-4">{error && <Notice type="error">{error}</Notice>}<Input label="Full name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required data-testid="input-register-name" /><div className="grid gap-4 sm:grid-cols-2"><Input label="Email" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required data-testid="input-register-email" /><Input label="Mobile" value={form.mobile} onChange={(e) => setForm({ ...form, mobile: e.target.value })} required data-testid="input-register-mobile" /></div><div className="grid gap-4 sm:grid-cols-2"><SelectField label="Ward" value={form.ward} onChange={(e) => setForm({ ...form, ward: e.target.value })} data-testid="select-register-ward">{wards.map((ward) => <option key={ward}>{ward}</option>)}</SelectField><Input label="Password" type="password" minLength={8} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required data-testid="input-register-password" /></div><TextArea label="Home address" value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} required data-testid="input-register-address" /><Button type="submit" disabled={register.isPending} className="mt-2 h-12" data-testid="button-register">{register.isPending ? <Loader2 className="animate-spin" size={17} /> : <ArrowRight size={17} />}Continue</Button></form><AuthFooter>Already registered? <Link href="/login" className="font-extrabold text-primary" data-testid="link-login">Sign in instead</Link></AuthFooter></AuthLayout>;
}

function VerifyOtpPage({ reset = false }: { reset?: boolean }) {
  const [, setLocation] = useLocation(); const email = localStorage.getItem("pending_email") || ""; const verify = useVerifyOtp(); const send = useSendOtp(); const [otp, setOtp] = useState(""); const [error, setError] = useState(""); const [sent, setSent] = useState("");
  const submit = (e: FormEvent) => { e.preventDefault(); setError(""); if (reset) { localStorage.setItem("reset_otp", otp); setLocation("/reset-password"); return; } verify.mutate({ data: { email, otp } }, { onSuccess: () => setLocation("/login"), onError: (err) => setError((err as Error).message || "That code was not accepted") }); };
  const resend = () => { send.mutate({ data: { email } }, { onSuccess: () => setSent("A fresh code is on its way.") }); };
  return <AuthLayout eyebrow={reset ? "Password recovery" : "One more step"} title="Check your messages." aside="A quick verification keeps your account—and your neighborhood reports—safe."><form onSubmit={submit} className="grid gap-5">{error && <Notice type="error">{error}</Notice>}{sent && <Notice>{sent}</Notice>}<div className="rounded-2xl bg-secondary p-4 text-sm text-muted-foreground">We sent a 6-digit code to <b className="text-foreground">{email || "your registered contact"}</b>.</div><Input label="Verification code" inputMode="numeric" maxLength={6} value={otp} onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))} placeholder="000000" className="text-center text-2xl tracking-[.45em]" required data-testid="input-otp" /><Button type="submit" disabled={verify.isPending} className="h-12" data-testid="button-verify">{verify.isPending ? <Loader2 className="animate-spin" size={17} /> : <Check size={17} />}{reset ? "Verify code" : "Verify account"}</Button><button type="button" onClick={resend} className="text-sm font-bold text-primary" data-testid="button-resend-otp">Resend code</button></form><AuthFooter><Link href="/login" className="font-extrabold text-primary" data-testid="link-back-login">Back to sign in</Link></AuthFooter></AuthLayout>;
}

function ForgotPasswordPage() {
  const [, setLocation] = useLocation(); const forgot = useForgotPassword(); const [email, setEmail] = useState(""); const [error, setError] = useState("");
  const submit = (e: FormEvent) => { e.preventDefault(); forgot.mutate({ data: { email } }, { onSuccess: () => { localStorage.setItem("pending_email", email); setLocation("/verify-otp?reset=true"); }, onError: (err) => setError((err as Error).message || "Could not send reset code") }); };
  return <AuthLayout eyebrow="Account recovery" title="Let’s get you back in." aside="The work in your ward shouldn’t wait for a forgotten password."><form onSubmit={submit} className="grid gap-5">{error && <Notice type="error">{error}</Notice>}<p className="text-sm leading-6 text-muted-foreground">Enter the email linked to your resident account and we’ll send a one-time code.</p><Input label="Email address" type="email" value={email} onChange={(e) => setEmail(e.target.value)} required data-testid="input-forgot-email" /><Button type="submit" disabled={forgot.isPending} className="h-12" data-testid="button-forgot">{forgot.isPending ? <Loader2 className="animate-spin" size={17} /> : <Send size={17} />}Send recovery code</Button></form><AuthFooter><Link href="/login" className="font-extrabold text-primary" data-testid="link-back-login">Back to sign in</Link></AuthFooter></AuthLayout>;
}

function ResetPasswordPage() {
  const [, setLocation] = useLocation(); const reset = useResetPassword(); const [form, setForm] = useState({ otp: localStorage.getItem("reset_otp") || "", newPassword: "" }); const [error, setError] = useState("");
  const submit = (e: FormEvent) => { e.preventDefault(); reset.mutate({ data: { email: localStorage.getItem("pending_email") || "", ...form } }, { onSuccess: () => { localStorage.removeItem("reset_otp"); setLocation("/login"); }, onError: (err) => setError((err as Error).message || "Could not reset password") }); };
  return <AuthLayout eyebrow="New password" title="Choose a fresh start." aside="Good civic work needs a secure home base."><form onSubmit={submit} className="grid gap-5">{error && <Notice type="error">{error}</Notice>}<Input label="Verification code" value={form.otp} onChange={(e) => setForm({ ...form, otp: e.target.value })} required data-testid="input-reset-otp" /><Input label="New password" type="password" minLength={8} value={form.newPassword} onChange={(e) => setForm({ ...form, newPassword: e.target.value })} required data-testid="input-new-password" /><Button type="submit" disabled={reset.isPending} className="h-12" data-testid="button-reset">{reset.isPending ? <Loader2 className="animate-spin" size={17} /> : <Check size={17} />}Set new password</Button></form></AuthLayout>;
}

function Shell({ children, admin = false }: { children: ReactNode; admin?: boolean }) {
  const [location, setLocation] = useLocation(); const [open, setOpen] = useState(false); const logout = useLogoutUser(); const user = currentUser(); const nav = admin ? [{ href: "/admin/dashboard", label: "Overview", icon: BarChart3 }, { href: "/admin/issues", label: "Issue queue", icon: ClipboardList }] : [{ href: "/dashboard", label: "Overview", icon: Home }, { href: "/report-issue", label: "Report an issue", icon: Plus }, { href: "/my-issues", label: "My issues", icon: FileText }];
  const signOut = () => logout.mutate(undefined, { onSettled: () => { clearSession(); setLocation("/login"); } });
  return <div className="noise min-h-[100dvh] bg-background"><div className="flex min-h-[100dvh]"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[268px] -translate-x-full flex-col bg-sidebar px-5 py-6 text-sidebar-foreground transition-transform duration-300 lg:static lg:translate-x-0 ${open ? "translate-x-0" : ""}`}><div className="flex items-center justify-between"><Logo dark /><button className="text-sidebar-foreground/70 lg:hidden" onClick={() => setOpen(false)} data-testid="button-close-menu"><X /></button></div><div className="mt-10 rounded-2xl border border-sidebar-border bg-sidebar-accent/40 p-4"><div className="label-mono text-sidebar-foreground/50">{admin ? "Administrator" : "Resident account"}</div><div className="mt-2 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-accent font-black text-primary">{initials(user?.name)}</span><div className="min-w-0"><div className="truncate text-sm font-extrabold">{user?.name || "Resident"}</div><div className="truncate text-xs text-sidebar-foreground/60">{user?.ward || "Your ward"}</div></div></div></div><nav className="mt-8 grid gap-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label.toLowerCase().replaceAll(" ", "-")}`} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition ${location === href ? "bg-sidebar-primary text-sidebar-primary-foreground" : "text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground"}`}><Icon size={18} />{label}</Link>)}</nav><div className="mt-auto grid gap-1 border-t border-sidebar-border pt-4"><Link href="/profile" onClick={() => setOpen(false)} className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="link-nav-profile"><UserRound size={18} />Profile</Link><button onClick={signOut} className="flex items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-bold text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="button-logout"><LogOut size={18} />Sign out</button></div></aside>{open && <button className="fixed inset-0 z-30 bg-primary/20 backdrop-blur-sm lg:hidden" onClick={() => setOpen(false)} aria-label="Close menu" /> }<main className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-border/70 bg-background/90 px-5 backdrop-blur-md sm:px-8"><button onClick={() => setOpen(true)} className="rounded-lg p-2 hover:bg-muted lg:hidden" data-testid="button-open-menu"><Menu /></button><div className="hidden lg:block"><div className="label-mono text-muted-foreground">{admin ? "Wardline / operations" : "Wardline / resident desk"}</div><div className="text-sm font-extrabold">{admin ? "Service operations" : "Your civic workspace"}</div></div><div className="flex items-center gap-3"><button className="relative rounded-xl p-2.5 text-muted-foreground transition hover:bg-muted" data-testid="button-notifications"><Bell size={18} /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-accent-foreground" /></button><div className="hidden h-8 w-px bg-border sm:block" /><span className="grid h-9 w-9 place-items-center rounded-full bg-secondary text-xs font-black text-primary">{initials(user?.name)}</span></div></header><div className="page-enter p-5 sm:p-8">{children}</div></main></div></div>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="label-mono text-muted-foreground">{eyebrow}</div><h1 className="display-serif mt-2 text-4xl leading-none sm:text-5xl">{title}</h1>{description && <p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>;
}
function StatCard({ label, value, note, accent = "primary", icon: Icon }: { label: string; value: number | string; note: string; accent?: string; icon: typeof Home }) {
  return <div className="relative overflow-hidden rounded-2xl border border-border bg-card p-5 shadow-sm"><div className={`absolute right-0 top-0 h-16 w-16 rounded-bl-[48px] ${accent === "accent" ? "bg-accent/20" : accent === "green" ? "bg-emerald-100" : "bg-primary/10"}`} /><Icon size={18} className="relative text-muted-foreground" /><div className="relative mt-6 text-3xl font-extrabold">{value}</div><div className="relative mt-1 text-sm font-bold">{label}</div><div className="relative mt-2 text-xs text-muted-foreground">{note}</div></div>;
}
function IssueRow({ issue, admin = false }: { issue: Issue; admin?: boolean }) {
  return <Link href={`${admin ? "/admin/issues/" : "/issues/"}${issue.id}`} data-testid={`row-issue-${issue.id}`} className="group grid grid-cols-[1fr_auto] gap-3 border-b border-border/70 px-1 py-4 transition hover:bg-secondary/45 sm:grid-cols-[minmax(0,1.5fr)_120px_110px_95px] sm:items-center sm:px-3"><div className="min-w-0"><div className="truncate text-sm font-extrabold group-hover:text-primary">{issue.title}</div><div className="mt-1 flex items-center gap-2 text-xs text-muted-foreground"><span>{issue.id.slice(0, 8).toUpperCase()}</span><span>·</span><span>{formatDate(issue.createdAt)}</span>{admin && <><span>·</span><span>{issue.ward}</span></>}</div></div><StatusPill status={issue.status} /><div className="hidden text-xs font-semibold text-muted-foreground sm:block">{issue.category}</div><div className="hidden justify-self-end sm:block"><PriorityPill priority={issue.priority} /></div></Link>;
}

function CitizenDashboard() {
  const user = currentUser(); const dashboard = useGetCitizenDashboard(); const data = dashboard.data as Dashboard | undefined; const [location, setLocation] = useLocation();
  if (dashboard.isLoading) return <LoadingState />; if (dashboard.isError) return <ErrorState onRetry={() => dashboard.refetch()} />;
  return <><PageHeading eyebrow={`Good morning, ${user?.name?.split(" ")[0] || "neighbor"}`} title="Your ward, at a glance." description="See what you’ve reported, what’s moving, and what’s already been put right." action={<Button onClick={() => setLocation("/report-issue")} data-testid="button-dashboard-report"><Plus size={17} />Report an issue</Button>} />
    <div className="grid gap-4 sm:grid-cols-3"><StatCard icon={ClipboardList} label="All issues" value={data?.total || 0} note="Across your reports" /><StatCard icon={Clock3} label="In progress" value={data?.inProgress || 0} note="Being looked into" accent="accent" /><StatCard icon={Check} label="Resolved" value={data?.resolved || 0} note="Closed with care" accent="green" /></div>
    <div className="mt-7 grid gap-6 lg:grid-cols-[1.35fr_.65fr]"><section className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-6"><div className="flex items-center justify-between"><div><div className="label-mono text-muted-foreground">Your activity</div><h2 className="mt-1 text-lg font-extrabold">Recent reports</h2></div><Link href="/my-issues" className="text-xs font-extrabold text-primary" data-testid="link-view-all-issues">View all <ArrowRight className="ml-1 inline" size={14} /></Link></div><div className="mt-4">{data?.recent?.length ? data.recent.map((issue) => <IssueRow issue={issue} key={issue.id} />) : <EmptyState title="No reports yet" description="When you spot something that needs attention, it’ll show up here." action={<Link href="/report-issue" className="font-bold text-primary" data-testid="link-empty-report">Report the first one</Link>} />}</div></section><section className="civic-grid relative overflow-hidden rounded-2xl bg-primary p-6 text-primary-foreground"><div className="absolute -right-10 -top-10 h-40 w-40 rounded-full border-[22px] border-accent/25" /><div className="label-mono text-accent">Small action, real impact</div><h2 className="display-serif relative mt-5 text-3xl leading-tight">See it.<br />Say it.<br /><span className="text-accent">Sort it.</span></h2><p className="relative mt-5 text-sm leading-6 text-primary-foreground/70">A clear report gives our teams a clear place to start. Add a landmark, choose a category, and we’ll take it from there.</p><Link href="/report-issue" className="relative mt-7 inline-flex items-center gap-2 text-sm font-extrabold text-accent" data-testid="link-dashboard-tip">Make a report <ArrowRight size={16} /></Link></section></div>
  </>;
}
function EmptyState({ title, description, action }: { title: string; description: string; action?: ReactNode }) {
  return <div className="py-12 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><FileText size={20} /></div><h3 className="mt-4 font-extrabold">{title}</h3><p className="mx-auto mt-1 max-w-xs text-sm leading-6 text-muted-foreground">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}

function ReportIssuePage() {
  const [, setLocation] = useLocation(); const create = useCreateIssue(); const user = currentUser(); const [error, setError] = useState(""); const [done, setDone] = useState(""); const [form, setForm] = useState<IssueInput>({ title: "", category: categories[0], description: "", ward: user?.ward || "Ward 01", location: "", landmark: "", priority: "Medium" as IssuePriority, image: null });
  const update = (key: keyof IssueInput, value: string) => setForm((old) => ({ ...old, [key]: value }));
  const handleImage = (file?: File) => {
    if (!file) return;
    if (!["image/jpeg", "image/png"].includes(file.type)) { setError("Please upload a JPG or PNG image."); return; }
    if (file.size > 5 * 1024 * 1024) { setError("Image size must be less than 5 MB."); return; }
    const reader = new FileReader();
    reader.onload = () => setForm((old) => ({ ...old, image: typeof reader.result === "string" ? reader.result : null }));
    reader.readAsDataURL(file);
  };
  const submit = (e: FormEvent) => { e.preventDefault(); setError(""); create.mutate({ data: form }, { onSuccess: (issue) => { queryClient.invalidateQueries({ queryKey: getGetIssuesQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetCitizenDashboardQueryKey() }); setDone(`Report ${issue.id.slice(0, 8).toUpperCase()} submitted.`); setTimeout(() => setLocation(`/issues/${issue.id}`), 700); }, onError: (err) => setError((err as Error).message || "Could not submit report") }); };
  return <><PageHeading eyebrow="New report" title="Put it on the map." description="Give our ward team the details they need to find the problem and get moving." /><div className="grid gap-6 lg:grid-cols-[1fr_320px]"><form onSubmit={submit} className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7">{error && <Notice type="error">{error}</Notice>}{done && <div className="mb-5"><Notice>{done}</Notice></div>}<div className="grid gap-5"><Input label="What needs attention?" placeholder="e.g. Streetlight out on Cedar Avenue" value={form.title} onChange={(e) => update("title", e.target.value)} required minLength={4} data-testid="input-issue-title" /><div className="grid gap-5 sm:grid-cols-2"><SelectField label="Category" value={form.category} onChange={(e) => update("category", e.target.value)} data-testid="select-issue-category">{categories.map((category) => <option key={category}>{category}</option>)}</SelectField><SelectField label="Priority" value={form.priority} onChange={(e) => update("priority", e.target.value)} data-testid="select-issue-priority">{["Low", "Medium", "High", "Critical"].map((priority) => <option key={priority}>{priority}</option>)}</SelectField></div><TextArea label="Describe the issue" placeholder="What happened? How is it affecting the neighborhood?" value={form.description} onChange={(e) => update("description", e.target.value)} required minLength={10} data-testid="textarea-issue-description" /><div className="grid gap-5 sm:grid-cols-2"><Input label="Location" placeholder="Street or intersection" value={form.location} onChange={(e) => update("location", e.target.value)} required data-testid="input-issue-location" /><Input label="Nearby landmark" placeholder="A shop, school, or park" value={form.landmark} onChange={(e) => update("landmark", e.target.value)} required data-testid="input-issue-landmark" /></div><label className="grid gap-2 text-sm font-bold text-foreground"><span>Issue image <span className="font-medium text-muted-foreground">(optional)</span></span><input type="file" accept=".jpg,.jpeg,.png,image/jpeg,image/png" onChange={(e) => handleImage(e.target.files?.[0])} className="rounded-xl border border-dashed border-input bg-secondary/35 px-3 py-3 text-sm" data-testid="input-issue-image" /><span className="text-xs font-medium text-muted-foreground">JPG or PNG, up to 5 MB.</span></label><div className="rounded-xl border border-dashed border-input bg-secondary/35 p-4"><div className="flex items-start gap-3"><MapPin size={18} className="mt-0.5 text-primary" /><div><div className="text-sm font-extrabold">Location clarity matters</div><p className="mt-1 text-xs leading-5 text-muted-foreground">A nearby landmark helps our team find the exact spot faster.</p></div></div></div><div className="flex flex-col-reverse justify-between gap-3 border-t border-border pt-5 sm:flex-row sm:items-center"><span className="text-xs text-muted-foreground">Fields marked above are required.</span><Button type="submit" disabled={create.isPending} data-testid="button-submit-issue">{create.isPending ? <Loader2 size={17} className="animate-spin" /> : <Send size={17} />}Submit report</Button></div></div></form><aside className="h-fit rounded-2xl bg-secondary p-6"><div className="grid h-10 w-10 place-items-center rounded-xl bg-accent text-primary"><Zap size={19} /></div><h3 className="mt-5 text-lg font-extrabold">What happens next?</h3><div className="mt-5 grid gap-5">{["We review the details", "The right team is assigned", "You follow progress here"].map((item, index) => <div className="flex gap-3" key={item}><span className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-primary text-xs font-black text-primary-foreground">{index + 1}</span><p className="pt-0.5 text-sm font-semibold">{item}</p></div>)}</div></aside></div></>;
}

function MyIssuesPage({ admin = false }: { admin?: boolean }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState(""); const [category, setCategory] = useState(""); const params = useMemo(() => ({ search: search || undefined, status: status || undefined, category: category || undefined }), [search, status, category]); const query = useGetIssues(params); const issues = query.data as Issue[] | undefined;
  return <><PageHeading eyebrow={admin ? "Operations queue" : "Your reports"} title={admin ? "Every issue, clearly." : "Your issue history."} description={admin ? "Filter the queue, open a report, and move it one step closer to resolved." : "A complete record of the things you’ve asked your ward to look into."} action={!admin && <Link href="/report-issue" className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground transition hover:-translate-y-0.5" data-testid="link-report-issue"><Plus size={17} />New report</Link>} /><div className="rounded-2xl border border-border bg-card shadow-sm"><div className="flex flex-col gap-3 border-b border-border p-4 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-3 text-muted-foreground" size={17} /><input type="search" placeholder="Search reports..." value={search} onChange={(e) => setSearch(e.target.value)} className="h-11 w-full rounded-xl border border-input bg-background pl-10 pr-3 text-sm outline-none focus:border-primary focus:ring-4 focus:ring-primary/10" data-testid="input-search-issues" /></label><div className="flex gap-3"><SelectField value={status} onChange={(e) => setStatus(e.target.value)} aria-label="Filter by status" className="min-w-36" data-testid="select-filter-status"><option value="">All statuses</option>{statuses.map((item) => <option key={item}>{item}</option>)}</SelectField><SelectField value={category} onChange={(e) => setCategory(e.target.value)} aria-label="Filter by category" className="hidden min-w-40 sm:block" data-testid="select-filter-category"><option value="">All categories</option>{categories.map((item) => <option key={item}>{item}</option>)}</SelectField><button className="grid h-11 w-11 shrink-0 place-items-center rounded-xl border border-input text-muted-foreground sm:hidden" data-testid="button-filter-mobile"><Filter size={17} /></button></div></div>{query.isLoading ? <div className="p-5"><LoadingState /></div> : query.isError ? <div className="p-5"><ErrorState onRetry={() => query.refetch()} /></div> : issues?.length ? <div className="px-4 pb-2"><div className="hidden grid-cols-[minmax(0,1.5fr)_120px_110px_95px] gap-3 px-3 pb-2 pt-4 text-[10px] font-black uppercase tracking-wider text-muted-foreground sm:grid"><span>Issue</span><span>Status</span><span>Category</span><span className="text-right">Priority</span></div>{issues.map((issue) => <IssueRow issue={issue} admin={admin} key={issue.id} />)}</div> : <EmptyState title="No issues match that" description="Try a different search or clear your filters to see more reports." action={<button onClick={() => { setSearch(""); setStatus(""); setCategory(""); }} className="font-bold text-primary" data-testid="button-clear-filters">Clear filters</button>} />}</div></>;
}

function IssueDetailPage({ admin = false }: { admin?: boolean }) {
  const params = useParams<{ id: string }>(); const issueQuery = useGetIssueById(params.id || ""); const issue = issueQuery.data as Issue | undefined; const updateStatus = useUpdateIssueStatus(); const updatePriority = useUpdateIssuePriority(); const updateIssue = useUpdateIssue(); const remove = useDeleteIssue(); const [, setLocation] = useLocation(); const [remark, setRemark] = useState(""); const [notice, setNotice] = useState("");
  if (issueQuery.isLoading) return <LoadingState />; if (issueQuery.isError || !issue) return <ErrorState onRetry={() => issueQuery.refetch()} />;
  const refresh = () => { queryClient.invalidateQueries({ queryKey: getGetIssueByIdQueryKey(issue.id) }); queryClient.invalidateQueries({ queryKey: getGetIssuesQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetAdminDashboardQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetCitizenDashboardQueryKey() }); };
  const changeStatus = (value: string) => updateStatus.mutate({ id: issue.id, data: { status: value, adminRemark: remark || undefined } }, { onSuccess: () => { setRemark(""); setNotice("Status updated."); refresh(); } }); const changePriority = (value: string) => updatePriority.mutate({ id: issue.id, data: { priority: value } }, { onSuccess: () => { setNotice("Priority updated."); refresh(); } }); const saveRemark = () => updateIssue.mutate({ id: issue.id, data: { adminRemark: remark } }, { onSuccess: () => { setRemark(""); setNotice("Remark saved."); refresh(); } }); const deleteIssue = () => { if (window.confirm("Delete this report?")) remove.mutate({ id: issue.id }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetIssuesQueryKey() }); setLocation(admin ? "/admin/issues" : "/my-issues"); } }); };
  return <><div className="mb-6"><Link href={admin ? "/admin/issues" : "/my-issues"} className="inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-primary" data-testid="link-back-issues"><ArrowLeft size={16} />Back to {admin ? "issue queue" : "your issues"}</Link></div><div className="grid gap-6 lg:grid-cols-[1fr_340px]"><main><div className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="label-mono text-muted-foreground">{issue.id.slice(0, 8).toUpperCase()} · {formatDate(issue.createdAt)}</div><h1 className="display-serif mt-3 max-w-2xl text-4xl leading-tight">{issue.title}</h1><div className="mt-4 flex flex-wrap items-center gap-2"><StatusPill status={issue.status} /><PriorityPill priority={issue.priority} /><span className="text-xs font-semibold text-muted-foreground">{issue.category}</span></div></div>{admin && <button onClick={deleteIssue} className="rounded-xl p-2 text-muted-foreground hover:bg-red-50 hover:text-red-700" data-testid="button-delete-issue"><Trash2 size={18} /></button>}</div><div className="mt-8 grid gap-5 border-t border-border pt-6"><div><div className="label-mono text-muted-foreground">Description</div><p className="mt-2 text-sm leading-7 text-foreground/80">{issue.description}</p></div><div className="grid gap-4 sm:grid-cols-2"><div className="rounded-xl bg-secondary p-4"><div className="label-mono text-muted-foreground">Location</div><div className="mt-2 flex gap-2 text-sm font-bold"><MapPin size={16} className="shrink-0 text-primary" />{issue.location}</div><div className="mt-1 pl-6 text-xs text-muted-foreground">Near {issue.landmark}</div></div><div className="rounded-xl bg-secondary p-4"><div className="label-mono text-muted-foreground">Reported by</div><div className="mt-2 text-sm font-bold">{issue.citizenName}</div><div className="mt-1 text-xs text-muted-foreground">{issue.ward} · {issue.citizenEmail}</div></div></div></div></div><div className="mt-6 rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7"><div className="label-mono text-muted-foreground">A clear trail</div><h2 className="mt-1 text-lg font-extrabold">Status history</h2><div className="mt-6 grid gap-0">{issue.history?.length ? issue.history.map((item, index) => <div className="relative flex gap-4 pb-6 last:pb-0" key={`${item.status}-${item.date}`}><div className="relative flex flex-col items-center"><span className={`z-10 grid h-7 w-7 place-items-center rounded-full ${index === 0 ? "bg-accent text-primary" : "bg-secondary text-muted-foreground"}`}><Check size={14} /></span>{index < issue.history.length - 1 && <span className="absolute top-7 h-full w-px bg-border" />}</div><div className="min-w-0 pb-1"><div className="flex flex-wrap items-center gap-2"><span className="text-sm font-extrabold">{item.status}</span><span className="text-xs text-muted-foreground">{formatDate(item.date)}</span></div><p className="mt-1 text-xs text-muted-foreground">Updated by {item.updatedBy}{item.remark ? ` · ${item.remark}` : ""}</p></div></div>) : <p className="text-sm text-muted-foreground">No status updates yet.</p>}</div></div></main><aside className="h-fit grid gap-4">{notice && <Notice>{notice}</Notice>}{admin ? <div className="rounded-2xl border border-border bg-card p-5 shadow-sm"><div className="label-mono text-muted-foreground">Move this report</div><h2 className="mt-1 text-lg font-extrabold">Update workflow</h2><div className="mt-5 grid gap-4"><SelectField label="Status" value={issue.status} onChange={(e) => changeStatus(e.target.value)} data-testid="select-admin-status">{statuses.map((item) => <option key={item}>{item}</option>)}</SelectField><SelectField label="Priority" value={issue.priority} onChange={(e) => changePriority(e.target.value)} data-testid="select-admin-priority">{["Low", "Medium", "High", "Critical"].map((item) => <option key={item}>{item}</option>)}</SelectField><TextArea label="Internal remark" placeholder="Add context for the resident..." value={remark} onChange={(e) => setRemark(e.target.value)} data-testid="textarea-admin-remark" /><Button type="button" onClick={saveRemark} disabled={!remark.trim() || updateIssue.isPending} data-testid="button-save-remark">{updateIssue.isPending ? <Loader2 size={16} className="animate-spin" /> : <MessageSquare size={16} />}Save remark</Button></div></div> : <div className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="grid h-10 w-10 place-items-center rounded-xl bg-accent text-primary"><MessageSquare size={19} /></div><h2 className="mt-5 text-lg font-extrabold">Need to add something?</h2><p className="mt-2 text-sm leading-6 text-primary-foreground/70">If the situation changes, submit a new note so the team has the latest context.</p><Link href="/report-issue" className="mt-5 inline-flex items-center gap-2 text-sm font-extrabold text-accent" data-testid="link-new-report-detail">New report <ArrowRight size={15} /></Link></div>}{issue.adminRemark && <div className="rounded-2xl border border-accent/40 bg-accent/15 p-5"><div className="label-mono text-accent-foreground">Ward team note</div><p className="mt-2 text-sm leading-6">{issue.adminRemark}</p></div>}</aside></div></>;
}

function ProfilePage() {
  const query = useGetProfile(); const update = useUpdateProfile(); const user = query.data as User | undefined; const [form, setForm] = useState({ name: "", mobile: "", address: "", ward: "" }); const [notice, setNotice] = useState(""); const [initialized, setInitialized] = useState(false);
  useEffect(() => { if (user && !initialized) { setForm({ name: user.name, mobile: user.mobile, address: user.address, ward: user.ward }); setInitialized(true); } }, [user, initialized]);
  if (query.isLoading) return <LoadingState />; if (query.isError) return <ErrorState onRetry={() => query.refetch()} />;
  const submit = (e: FormEvent) => { e.preventDefault(); update.mutate({ data: form }, { onSuccess: (next) => { localStorage.setItem("ward_user", JSON.stringify(next)); setNotice("Profile saved."); queryClient.setQueryData(getGetProfileQueryKey(), next); } }); };
  return <><PageHeading eyebrow="Account" title="Your profile." description="Keep your details current so ward teams know how to follow up." /><div className="max-w-2xl rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7"><div className="mb-7 flex items-center gap-4 border-b border-border pb-6"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-accent text-xl font-black text-primary">{initials(user?.name)}</span><div><div className="font-extrabold">{user?.name}</div><div className="text-sm text-muted-foreground">{user?.email}</div></div></div><form onSubmit={submit} className="grid gap-5">{notice && <Notice>{notice}</Notice>}<Input label="Full name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} data-testid="input-profile-name" /><div className="grid gap-5 sm:grid-cols-2"><Input label="Mobile" value={form.mobile} onChange={(e) => setForm({ ...form, mobile: e.target.value })} data-testid="input-profile-mobile" /><SelectField label="Ward" value={form.ward} onChange={(e) => setForm({ ...form, ward: e.target.value })} data-testid="select-profile-ward">{wards.map((ward) => <option key={ward}>{ward}</option>)}</SelectField></div><TextArea label="Home address" value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} data-testid="textarea-profile-address" /><div className="flex justify-end border-t border-border pt-5"><Button type="submit" disabled={update.isPending} data-testid="button-save-profile">{update.isPending ? <Loader2 size={17} className="animate-spin" /> : <Check size={17} />}Save changes</Button></div></form></div></>;
}

function AdminDashboardPage() {
  const query = useGetAdminDashboard(); const data = query.data as AdminDashboard | undefined; const [location, setLocation] = useLocation(); if (query.isLoading) return <LoadingState />; if (query.isError) return <ErrorState onRetry={() => query.refetch()} />;
  const stats = [{ label: "Total reports", value: data?.total || 0, note: "Across all wards", icon: ClipboardList }, { label: "Needs review", value: (data?.submitted || 0) + (data?.underReview || 0), note: "Awaiting next action", icon: Clock3 }, { label: "In progress", value: data?.inProgress || 0, note: "With a working team", icon: Zap }, { label: "Resolved", value: data?.resolved || 0, note: "Closed this cycle", icon: Check }];
  return <><PageHeading eyebrow="Operations overview" title="Good work starts here." description="A live view of what residents are telling you—and where the queue needs a nudge." action={<Button onClick={() => setLocation("/admin/issues")} data-testid="button-admin-open-queue"><ClipboardList size={17} />Open issue queue</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map((stat) => <StatCard {...stat} key={stat.label} accent={stat.label === "Resolved" ? "green" : stat.label === "Needs review" ? "accent" : "primary"} />)}</div><div className="mt-7 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-border bg-card p-6 shadow-sm"><div className="flex items-center justify-between"><div><div className="label-mono text-muted-foreground">Workload shape</div><h2 className="mt-1 text-lg font-extrabold">By category</h2></div><BarChart3 size={20} className="text-muted-foreground" /></div><div className="mt-7 grid gap-4">{Object.entries(data?.byCategory || {}).map(([category, count]) => { const width = Math.max(8, ((count as number) / Math.max(1, data?.total || 1)) * 100); return <div key={category}><div className="mb-2 flex justify-between text-xs font-bold"><span>{category}</span><span className="text-muted-foreground">{count}</span></div><div className="h-2 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-primary transition-all duration-700" style={{ width: `${width}%` }} /></div></div>; })}</div></section><section className="relative overflow-hidden rounded-2xl bg-primary p-6 text-primary-foreground"><div className="absolute -right-14 -top-14 h-48 w-48 rounded-full border-[24px] border-accent/20" /><div className="relative label-mono text-accent">Today’s focus</div><h2 className="display-serif relative mt-5 text-3xl leading-tight">Make the next<br /><span className="text-accent">right handoff.</span></h2><p className="relative mt-5 max-w-sm text-sm leading-6 text-primary-foreground/70">A timely status update is often the difference between a report feeling lost and a resident feeling heard.</p><Button variant="secondary" onClick={() => setLocation("/admin/issues")} className="relative mt-7" data-testid="button-admin-focus">Review queue <ArrowRight size={16} /></Button></section></div></>;
}

function AppRouter() {
  const [location] = useLocation(); const user = currentUser(); const isAuth = ["/login", "/register", "/verify-otp", "/forgot-password", "/reset-password"].some((path) => location.startsWith(path)); const isAdmin = location.startsWith("/admin");
  useEffect(() => { document.title = location.startsWith("/admin") ? "Wardline · Operations" : "Wardline · Civic service"; }, [location]);
  if (isAuth) return <Switch><Route path="/login" component={LoginPage} /><Route path="/register" component={RegisterPage} /><Route path="/verify-otp">{() => <VerifyOtpPage reset={new URLSearchParams(window.location.search).get("reset") === "true"} />}</Route><Route path="/forgot-password" component={ForgotPasswordPage} /><Route path="/reset-password" component={ResetPasswordPage} /><Route component={NotFound} /></Switch>;
  if (!user) return <LoginPage />;
  if (isAdmin && user.role !== "admin") return <RedirectToDashboard />;
  return <Shell admin={isAdmin}><Switch><Route path="/dashboard" component={CitizenDashboard} /><Route path="/report-issue" component={ReportIssuePage} /><Route path="/my-issues">{() => <MyIssuesPage />}</Route><Route path="/issues/:id">{() => <IssueDetailPage />}</Route><Route path="/profile" component={ProfilePage} /><Route path="/admin/dashboard" component={AdminDashboardPage} /><Route path="/admin/issues">{() => <MyIssuesPage admin />}</Route><Route path="/admin/issues/:id">{() => <IssueDetailPage admin />}</Route><Route path="/"><RedirectToDashboard /></Route><Route component={NotFound} /></Switch></Shell>;
}
function RedirectToDashboard() { const [, setLocation] = useLocation(); useEffect(() => { const user = currentUser(); setLocation(user?.role === "admin" ? "/admin/dashboard" : "/dashboard"); }, [setLocation]); return <LoadingState />; }
function Router() { const [location] = useLocation(); return <ErrorBoundary resetKey={location}><AppRouter /></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><Router /></WouterRouter></QueryClientProvider>; }
export default App;